"""Prepare a reproducible GitHub transfer from an immutable, coordinator-selected Git commit.

This program only reads Git objects and writes a fresh transfer directory outside
the repository. It never stages files, writes Git objects, changes refs, or calls
GitHub. Text blobs are batched through create_tree, binary blobs use base64
create_blob, and a final SHA-only tree installs every duplicate path exactly once.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[3]


def git(*args):
    return subprocess.check_output(['git', *map(str, args)], cwd=ROOT)


def check(condition, message):
    if not condition:
        raise ValueError(message)


def git_hash(kind, payload):
    return hashlib.sha1(kind.encode() + b' ' + str(len(payload)).encode() + b'\0' + payload).hexdigest()


def sha(data):
    return hashlib.sha256(data).hexdigest()


def leaves(commit):
    result = {}
    for item in git('ls-tree', '-r', '-z', commit).split(b'\0'):
        if not item:
            continue
        header, name = item.split(b'\t', 1)
        mode, kind, oid = header.decode().split()
        path = name.decode('utf-8')
        check(path not in result, 'Duplicate Git path')
        result[path] = {'mode': mode, 'type': kind, 'sha': oid}
    return result


def tree_hash(mapping):
    root = {}
    for path, entry in mapping.items():
        names = path.split('/')
        node = root
        for name in names[:-1]:
            child = node.setdefault(name, {})
            check(isinstance(child, dict), 'Intermediate file/directory conflict: ' + path)
            node = child
        check(names[-1] not in node, 'Duplicate tree entry: ' + path)
        node[names[-1]] = (entry['mode'], entry['sha'])

    def encode(node):
        entries = []
        for name, value in node.items():
            if isinstance(value, dict):
                mode, oid, order = '40000', encode(value), (name + '/').encode()
            else:
                mode, oid = value
                order = name.encode()
            entries.append((order, mode.encode() + b' ' + name.encode() + b'\0' + bytes.fromhex(oid)))
        return git_hash('tree', b''.join(body for _, body in sorted(entries)))

    return encode(root)


def write_json(path, value):
    with path.open('x') as stream:
        json.dump(value, stream, ensure_ascii=True, indent=2, sort_keys=True)
        stream.write('\n')


def index_identity():
    index = Path(git('rev-parse', '--git-path', 'index').decode().strip())
    if not index.is_absolute():
        index = ROOT / index
    return {'path': str(index), 'sha256': sha(index.read_bytes())}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--commit', required=True, help='Immutable local commit selected by the coordinator')
    parser.add_argument('--parent', required=True, help='Expected current remote branch head and sole commit parent')
    parser.add_argument('--branch', default='GH-0000-lmdb-lazy-result-coordinates')
    parser.add_argument('--repository', default='HASMAC-AS/rdf4j')
    parser.add_argument('--output', type=Path, required=True, help='Fresh transfer directory outside the repository')
    parser.add_argument('--text-batch-bytes', type=int, default=750_000)
    args = parser.parse_args()
    check(args.text_batch_bytes >= 100_000, 'Text batch budget is too small')
    target_commit = git('rev-parse', '--verify', args.commit + '^{commit}').decode().strip()
    parent_commit = git('rev-parse', '--verify', args.parent + '^{commit}').decode().strip()
    parents = git('show', '-s', '--format=%P', target_commit).decode().split()
    check(parents == [parent_commit], 'Selected commit must have exactly the expected remote parent')
    head_before = git('rev-parse', 'HEAD').decode().strip()
    index_before = index_identity()
    out = args.output.resolve()
    check(not out.is_relative_to(ROOT), 'Keep regenerable transfer payloads outside the Git working tree')
    out.mkdir(parents=True, exist_ok=False)
    base = leaves(parent_commit)
    target = leaves(target_commit)
    base_tree = git('rev-parse', parent_commit + '^{tree}').decode().strip()
    target_tree = git('rev-parse', target_commit + '^{tree}').decode().strip()
    check(tree_hash(base) == base_tree and tree_hash(target) == target_tree,
          'Independent Git tree hashing did not reproduce the selected immutable objects')
    changes = sorted(path for path in base.keys() | target.keys() if base.get(path) != target.get(path))
    check(changes, 'Selected checkpoint has no tree changes')
    known_blobs = {entry['sha'] for entry in base.values() if entry['type'] == 'blob'}
    new_blobs = {}
    for path in changes:
        entry = target.get(path)
        if entry is None or entry['type'] != 'blob' or entry['sha'] in known_blobs:
            continue
        blob = new_blobs.setdefault(entry['sha'], {'paths': [], 'canonicalPath': path})
        blob['paths'].append(path)
    text_entries, binaries, blob_records = [], [], []
    for oid, record in new_blobs.items():
        data = git('cat-file', 'blob', oid)
        check(git_hash('blob', data) == oid, 'Git object does not match its claimed identity')
        try:
            text = data.decode('utf-8')
            textual = b'\0' not in data
        except UnicodeDecodeError:
            textual = False
        blob_records.append({'sha': oid, 'bytes': len(data), 'sha256': sha(data),
                             'encoding': 'utf-8' if textual else 'base64', **record})
        if textual:
            path = record['canonicalPath']
            text_entries.append({'path': path, 'mode': target[path]['mode'], 'type': 'blob', 'content': text})
        else:
            payload = out / ('blob-' + oid + '.base64')
            with payload.open('xb') as stream:
                stream.write(base64.b64encode(data))
            binaries.append({'expectedBlobSha': oid, 'bytes': len(data), 'payloadFile': str(payload),
                             'payloadSha256': sha(payload.read_bytes()), 'paths': record['paths']})

    # Only one canonical path per newly uploaded text blob is changed in these
    # intermediate trees. Duplicate aliases wait for the final SHA-only request.
    batches, pending, pending_bytes = [], [], 0
    for entry in text_entries:
        size = len(json.dumps(entry, ensure_ascii=True, separators=(',', ':')).encode())
        if pending and pending_bytes + size > args.text_batch_bytes:
            batches.append(pending)
            pending, pending_bytes = [], 0
        pending.append(entry)
        pending_bytes += size
    if pending:
        batches.append(pending)
    current = dict(base)
    current_tree = base_tree
    steps = []
    for number, entries in enumerate(batches):
        for entry in entries:
            current[entry['path']] = target[entry['path']]
        expected = tree_hash(current)
        payload = out / f'text-batch-{number:03d}.json'
        write_json(payload, entries)
        steps.append({'ordinal': number, 'baseTreeSha': current_tree, 'expectedTreeSha': expected,
                      'entryCount': len(entries), 'payloadFile': str(payload),
                      'payloadBytes': payload.stat().st_size, 'payloadSha256': sha(payload.read_bytes())})
        current_tree = expected

    final_entries = []
    for path in changes:
        entry = target.get(path)
        if entry is None:
            final_entries.append({'path': path, 'mode': base[path]['mode'], 'type': base[path]['type'], 'sha': None})
            current.pop(path, None)
        else:
            final_entries.append({'path': path, **entry})
            current[path] = entry
    check(current == target and tree_hash(current) == target_tree, 'Final transfer does not reproduce the selected tree')
    final_payload = out / 'final-tree-entries.json'
    write_json(final_payload, final_entries)
    message = git('cat-file', 'commit', target_commit).split(b'\n\n', 1)[1].decode('utf-8').rstrip('\n')
    write_json(out / 'new-blob-manifest.json', blob_records)
    plan = {'format': 1, 'repository': args.repository, 'branch': args.branch, 'localCommit': target_commit,
        'expectedRemoteParent': parent_commit, 'baseTreeSha': base_tree, 'targetTreeSha': target_tree,
        'message': message, 'changedPaths': len(changes), 'newUniqueBlobs': len(new_blobs),
        'newUniqueBytes': sum(item['bytes'] for item in blob_records),
        'alreadyPresentBlobPaths': sum(target[path]['type'] == 'blob' and target[path]['sha'] in known_blobs
                                      for path in changes if path in target),
        'binaryUploads': binaries, 'textTreeBatches': steps,
        'finalTree': {'baseTreeSha': current_tree, 'expectedTreeSha': target_tree,
                      'payloadFile': str(final_payload), 'payloadSha256': sha(final_payload.read_bytes()),
                      'entryCount': len(final_entries)},
        'newBlobManifestFile': str(out / 'new-blob-manifest.json'),
        'newBlobManifestSha256': sha((out / 'new-blob-manifest.json').read_bytes()),
        'preparationScript': {'path': str(Path(__file__).resolve()), 'sha256': sha(Path(__file__).read_bytes())},
        'localHeadBefore': head_before, 'localIndexBefore': index_before,
        'publicationPolicy': 'Read remote ref and require the expected parent before mutation. Verify every returned blob/tree SHA. Create the commit with the exact tree and parent; verify raw Git Data metadata. Update the existing branch only with expected_sha and force=false, then verify the ref again.',
        'gitObjectIndexOrRefWrites': False, 'githubCalls': 0}
    check(git('rev-parse', 'HEAD').decode().strip() == head_before and index_identity() == index_before,
          'Local HEAD or index changed during read-only preparation; inspect concurrent work before publication')
    write_json(out / 'transfer-plan.json', plan)
    print(json.dumps({'plan': str(out / 'transfer-plan.json'), 'targetTreeSha': target_tree,
        'changedPaths': len(changes), 'binaryBlobUploads': len(binaries), 'textTreeBatches': len(steps),
        'newUniqueBytes': plan['newUniqueBytes'], 'githubCalls': 0, 'gitWrites': False}, indent=2))


if __name__ == '__main__':
    main()
